Looking at the kernel, I need to:

1. Add HLS INTERFACE pragmas for the pointer arrays and scalar arguments
2. Add PIPELINE pragmas to the innermost loops
3. Add ARRAY_PARTITION for arrays that need parallel access
4. Keep the algorithm unchanged

The key observations:
- The `C`, `A`, `B` arrays are 2D passed by pointer — need m_axi interfaces
- The innermost `j` loop inside the `k` loop is the hot path — pipeline it
- The `j` loop for the beta scaling is also pipelineable
- Arrays are fixed size (NI×NJ, NI×NK, NK×NJ) — can partition along the innermost dimension for parallel access

Since the arrays are passed as 2D arrays (not pointers to flat buffers), and they're fixed-size on the stack/global, the best approach is to pipeline the innermost loops and partition appropriately. The 2D arrays decay to pointers in the interface, so we treat them as m_axi.

```cpp
#include "gemm.h"

extern "C" {

void kernel_gemm(  
		 double alpha,
		 double beta,
		 double C[ NI + 0][NJ + 0],
		 double A[ NI + 0][NK + 0],
		 double B[ NK + 0][NJ + 0])
{
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta  bundle=control
#pragma HLS INTERFACE s_axilite port=C     bundle=control
#pragma HLS INTERFACE s_axilite port=A     bundle=control
#pragma HLS INTERFACE s_axilite port=B     bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local tile buffers to stage from global memory for reuse
    double l_A[NI][NK];
    double l_B[NK][NJ];
    double l_C[NI][NJ];

#pragma HLS ARRAY_PARTITION variable=l_A cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=l_B cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=l_C cyclic factor=8 dim=2

    // Load A from global memory
    load_A_i: for (int i = 0; i < NI; i++) {
        load_A_k: for (int k = 0; k < NK; k++) {
#pragma HLS PIPELINE II=1
            l_A[i][k] = A[i][k];
        }
    }

    // Load B from global memory
    load_B_k: for (int k = 0; k < NK; k++) {
        load_B_j: for (int j = 0; j < NJ; j++) {
#pragma HLS PIPELINE II=1
            l_B[k][j] = B[k][j];
        }
    }

    // Load C from global memory
    load_C_i: for (int i = 0; i < NI; i++) {
        load_C_j: for (int j = 0; j < NJ; j++) {
#pragma HLS PIPELINE II=1
            l_C[i][j] = C[i][j];
        }
    }

    const int ni = NI;
    const int nj = NJ;
    const int nk = NK;

    int i, j, k;
    for (i = 0; i < ni; i++) {
        // Scale C[i][j] by beta
        for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
            l_C[i][j] *= beta;
        }
        // Accumulate alpha * A[i][k] * B[k][j] into C[i][j]
        for (k = 0; k < nk; k++) {
            for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
                l_C[i][j] += alpha * l_A[i][k] * l_B[k][j];
            }
        }
    }

    // Store C back to global memory
    store_C_i: for (int i = 0; i < NI; i++) {
        store_C_j: for (int j = 0; j < NJ; j++) {
#pragma HLS PIPELINE II=1
            C[i][j] = l_C[i][j];
        }
    }
}

} // extern "C"
```

Looking at the current code, it already has local buffers (l_A, l_B, l_C) but they're sized for the entire matrices (NI×NK, NK×NJ, NI×NJ). True **tiling** means breaking the computation into smaller tiles/chunks so that:
1. Smaller local buffers fit better in on-chip memory
2. Data reuse is improved within each tile
3. Load/compute/store phases are clearly separated per tile

I'll tile across the `i` and `j` dimensions with a tile size of 16, keeping `k` as the full inner dimension per tile. This restructures the loop nest around tiles and uses smaller local buffers.

```cpp
#include "gemm.h"

// Tile sizes for tiling optimization
#define TILE_I 16
#define TILE_J 16

extern "C" {

static void load_tile_A(double l_A[TILE_I][NK],
                        double A[NI][NK],
                        int i0)
{
    for (int i = 0; i < TILE_I; i++) {
        int gi = i0 + i;
        if (gi < NI) {
            for (int k = 0; k < NK; k++) {
#pragma HLS PIPELINE II=1
                l_A[i][k] = A[gi][k];
            }
        }
    }
}

static void load_tile_B(double l_B[TILE_J][NK],
                        double B[NK][NJ],
                        int j0)
{
    for (int j = 0; j < TILE_J; j++) {
        int gj = j0 + j;
        if (gj < NJ) {
            for (int k = 0; k < NK; k++) {
#pragma HLS PIPELINE II=1
                l_B[j][k] = B[k][gj];
            }
        }
    }
}

static void load_tile_C(double l_C[TILE_I][TILE_J],
                        double C[NI][NJ],
                        int i0, int j0)
{
    for (int i = 0; i < TILE_I; i++) {
        int gi = i0 + i;
        if (gi < NI) {
            for (int j = 0; j < TILE_J; j++) {
                int gj = j0 + j;
#pragma HLS PIPELINE II=1
                if (gj < NJ)
                    l_C[i][j] = C[gi][gj];
            }
        }
    }
}

static void compute_tile(double l_C[TILE_I][TILE_J],
                         double l_A[TILE_I][NK],
                         double l_B[TILE_J][NK],
                         double alpha, double beta)
{
    // Scale C tile by beta
    for (int i = 0; i < TILE_I; i++) {
        for (int j = 0; j < TILE_J; j++) {
#pragma HLS PIPELINE II=1
            l_C[i][j] *= beta;
        }
    }

    // Accumulate alpha * A[i][k] * B[k][j] into C tile
    // Note: l_B is stored as [j][k] for better access pattern
    for (int i = 0; i < TILE_I; i++) {
        for (int k = 0; k < NK; k++) {
            for (int j = 0; j < TILE_J; j++) {
#pragma HLS PIPELINE II=1
                l_C[i][j] += alpha * l_A[i][k] * l_B[j][k];
            }
        }
    }
}

static void store_tile_C(double l_C[TILE_I][TILE_J],
                         double C[NI][NJ],
                         int i0, int j0)
{
    for (int i = 0; i < TILE_I; i++) {
        int gi = i0 + i;
        if (gi < NI) {
            for (int j = 0; j < TILE_J; j++) {
                int gj = j0 + j;
#pragma HLS PIPELINE II=1
                if (gj < NJ)
                    C[gi][gj] = l_C[i][j];
            }
        }
    }
}

void kernel_gemm(  
		 double alpha,
		 double beta,
		 double C[ NI + 0][NJ + 0],
		 double A[ NI + 0][NK + 0],
		 double B[ NK + 0][NJ + 0])
{
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta  bundle=control
#pragma HLS INTERFACE s_axilite port=C     bundle=control
#pragma HLS INTERFACE s_axilite port=A     bundle=control
#pragma HLS INTERFACE s_axilite port=B     bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local tile buffers - much smaller than full matrices
    double l_A[TILE_I][NK];
    double l_B[TILE_J][NK];
    double l_C[TILE_I][TILE_J];

#pragma HLS ARRAY_PARTITION variable=l_A cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=l_B cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=l_C complete dim=2

    // Tile over i and j dimensions
    tile_i: for (int i0 = 0; i0 < NI; i0 += TILE_I) {
        tile_j: for (int j0 = 0; j0 < NJ; j0 += TILE_J) {

            // --- LOAD PHASE ---
            // Load A tile: rows [i0..i0+TILE_I), all K columns
            load_tile_A(l_A, A, i0);

            // Load B tile: cols [j0..j0+TILE_J), all K rows
            // Stored transposed as [j][k] for sequential k access in compute
            load_tile_B(l_B, B, j0);

            // Load C tile: rows [i0..i0+TILE_I), cols [j0..j0+TILE_J)
            load_tile_C(l_C, C, i0, j0);

            // --- COMPUTE PHASE ---
            // Operates entirely on local tile buffers
            compute_tile(l_C, l_A, l_B, alpha, beta);

            // --- STORE PHASE ---
            // Write computed C tile back to global memory
            store_tile_C(l_C, C, i0, j0);
        }
    }
}

} // extern "C"
```

**Key changes from the original:**

1. **Smaller tile buffers**: Instead of `l_A[NI][NK]`, `l_B[NK][NJ]`, `l_C[NI][NJ]` (full matrices), now using `l_A[TILE_I][NK]`, `l_B[TILE_J][NK]`, `l_C[TILE_I][TILE_J]` — much smaller on-chip storage.

2. **True tiling loop structure**: Outer `tile_i` / `tile_j` loops iterate over 16×16 tiles; inner loops process one tile at a time.

3. **Separated load/compute/store phases**: Each tile goes through `load_tile_A()`, `load_tile_B()`, `load_tile_C()` → `compute_tile()` → `store_tile_C()` as distinct functions.

4. **B stored transposed** as `[j][k]` in the local buffer for better sequential `k` access during the compute inner loop.

5. **Complete partition on l_C dim=2** (16 elements) enables parallel access to all j-elements of a C row during compute.

Looking at the current code, I need to add pipeline pragmas to the innermost compute loops, along with appropriate array partitioning and dependence pragmas to enable effective pipelining.

Key observations:
1. The `compute_tile` function has the critical inner loop `for (int j ...)` inside `for (int i ...) for (int k ...)` - this needs `PIPELINE II=1` with array partitioning on `l_C[i][j]`
2. `l_C` has a loop-carried dependency through accumulation in the k-loop - need `DEPENDENCE inter false` since each `(i,j)` pair only depends on same iteration
3. Local arrays `l_A`, `l_B`, `l_C` need partitioning to support parallel access in the pipeline
4. The load/store functions already have `PIPELINE II=1` but need matching partitioning on the local buffers passed in

