#pragma HLS ARRAY_PARTITION variable=l_A cyclic factor=8 dim=2
    for (int i = 0; i < TILE_I; i++) {
        int gi = i0 + i;
        if (gi < NI) {
            for (int k = 0; k < NK; k++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=80 max=80
                l_A[i][k] = A[gi][k];
            }
