        for (int j = 0; j < TILE_J; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
#pragma HLS DEPENDENCE variable=l_C inter false
            l_C[i][j] *= beta;
        }
