Looking at the current code, I need to apply UNROLL optimization to the inner loops in `compute_tile` where parallelism is beneficial. The `j` loop in the accumulation phase is currently pipelined but can be unrolled to increase data parallelism. I'll unroll the `j` loop by a factor of 8 (since TILE_J=16, factor 8 divides evenly) and adjust array partitioning accordingly.

The key changes:
1. Unroll the inner `j` loop in `compute_tile` by factor 8
2. Unroll the `j` loop in the beta-scaling section by factor 8
3. Adjust `l_C` partitioning to match the unroll factor (complete dim=2 already covers this since TILE_J=16)
4. Ensure `l_B` partitioning on dim=1 (j dimension) matches unroll factor

```cpp
#include "gemm.h"

// Tile sizes for tiling optimization
#define TILE_I 16
#define TILE_J 16

extern "C" {

static void load_tile_A(double l_A[TILE_I][NK],
                        double A[NI][NK],
                        int i0)
{
#pragma HLS ARRAY_PARTITION variable=l_A cyclic factor=8 dim=2
    for (int i = 0; i < TILE_I; i++) {
        int gi = i0 + i;
        if (gi < NI) {
            for (int k = 0; k < NK; k++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=80 max=80
                l_A[i][k] = A[gi][k];
            }
        }
    }
}

static void load_tile_B(double l_B[TILE_J][NK],
                        double B[NK][NJ],
                        int j0)
{
#pragma HLS ARRAY_PARTITION variable=l_B cyclic factor=8 dim=2
    for (int j = 0; j < TILE_J; j++) {
        int gj = j0 + j;
        if (gj < NJ) {
            for (int k = 0; k < NK; k++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=80 max=80
                l_B[j][k] = B[k][gj];
            }
        }
    }
}

static void load_tile_C(double l_C[TILE_I][TILE_J],
                        double C[NI][NJ],
                        int i0, int j0)
{
#pragma HLS ARRAY_PARTITION variable=l_C complete dim=2
    for (int i = 0; i < TILE_I; i++) {
        int gi = i0 + i;
        if (gi < NI) {
            for (int j = 0; j < TILE_J; j++) {
                int gj = j0 + j;
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
                if (gj < NJ)
                    l_C[i][j] = C[gi][gj];
            }
        }
    }
